/** 与双端视觉基线使用同一公开正文；围栏内的标题不属于正文目录。 */
export const longReadmeAppendix =
  '\n\n' +
  Array.from(
    { length: 12 },
    (_, index) =>
      `## 第${index + 1}章 · 一起收集日常的故事\n\n` +
      '在春日书房里，角色会先认真倾听，再用自然、清晰的表达回应你的想法。你可以分享一天里的小事，也可以慢慢写下想完成的故事。保留各自的边界，给每一种情绪留出空间。\n\n'.repeat(
        4,
      ),
  ).join('\n') +
  '\n## 使用建议\n\n重复标题仍应分别定位\n\n补充说明\n========\n\n支持Markdown的下划线标题\n\n```markdown\n## 代码里的标题不应进入目录\n```\n';
